/* ============ MY EVC — v9 : back-office selon la charte UI ============ */
const UVA_OLD = {}; ['a-parametres','a-roles'].forEach(id => UVA_OLD[id] = VIEWS[id].render);
uReg('prt','ftb','sest','rper','rtab');

/* ----- Données dérivées (déterministes) ----- */
const uBal = s => Math.max(0, s.total - s.paid);
const uPayTag = s => { const b = uBal(s), h = hueOf(s.id); if (s.status==='Certifié' || b<=0) return ['Soldé','info']; if (h%4===0) return ['En retard','bad']; if (h%4===1) return ['Échéance proche','warn']; return ['À jour','ok']; };
const uDoss = s => hueOf(s.name)%6===0 ? ['Incomplet','bad'] : ['Complet','ok'];
const uMoy = s => (9 + (hueOf(s.id)%80)/10);
const uLate = () => S.students.filter(s=>s.status==='Actif' && uPayTag(s)[0]==='En retard').map(s=>{ const h = hueOf(s.id); return {s, amount:Math.min(uBal(s), 90000 + (h%5)*15000), days:3 + h%24, last:(S.relances||{})[s.id] || ['SMS + e-mail · il y a 2 jours','Appel · il y a 5 jours','E-mail · hier','SMS · il y a 2 jours'][h%4]}; }).sort((a,b)=>b.days-a.days);
const uOctTx = () => allTx().filter(t=>!t.cancelled && /\/10\/2026$/.test(t.d));
const uM = n => (n/1e6).toFixed(n>=1e7?1:2).replace('.',',').replace(/,?0+$/,'') + ' M';
const uAgo = d => { const [dd,mm,yy] = d.split('/').map(Number), n = Math.round((new Date(2026,9,22) - new Date(yy,mm-1,dd))/86400000); return n<=0 ? "Aujourd'hui" : n===1 ? 'Hier' : `Il y a ${n} jours`; };
const uAgoN = d => { const [dd,mm,yy] = d.split('/').map(Number); return Math.round((new Date(2026,9,22) - new Date(yy,mm-1,dd))/86400000); };
const uRoleTone = r => /Super|Direction/.test(r) ? 'acc' : /pédagogique|certification/.test(r) ? 'mute' : /financier/.test(r) ? 'ok' : /Formateur/.test(r) ? 'info' : 'grey';

/* ----- Graphique en barres groupées (charte) ----- */
function uBars2(cats, a, b, {h=250, la='2026', lb='2025'}={}){
  const W = 760, pl = 12, pr = 12, pt = 26, pb = 34, ih = h-pt-pb, iw = W-pl-pr, max = Math.max(...a, ...b)*1.12, gw = iw/cats.length, bw = Math.min(20, gw/3.2);
  let g = `<line x1="${pl}" x2="${W-pr}" y1="${pt+ih}" y2="${pt+ih}" stroke="var(--line)"/>`;
  cats.forEach((c,i)=>{ const x = pl + gw*i + gw/2, hb = b[i]/max*ih, ha = a[i]/max*ih;
    g += `<rect class="ub-b" x="${x-bw-2}" y="${pt+ih-hb}" width="${bw}" height="${hb}" rx="4" fill="#C9C6E8" style="--d:${i*40}ms"><title>${lb} — ${c} : ${b[i]}</title></rect>`;
    g += `<rect class="ub-b" x="${x+2}" y="${pt+ih-ha}" width="${bw}" height="${ha}" rx="4" fill="var(--i900)" style="--d:${i*40+20}ms"><title>${la} — ${c} : ${a[i]}</title></rect>`;
    g += `<text x="${x+2+bw/2}" y="${pt+ih-ha-8}" text-anchor="middle" class="ub-v">${a[i]}</text><text x="${x}" y="${h-10}" text-anchor="middle" class="ub-c">${c}</text>`; });
  return `<svg class="u-chart" viewBox="0 0 ${W} ${h}" width="100%" role="img" aria-label="Nouvelles inscriptions par mois, ${la} et ${lb}">${g}</svg>`;
}
function uLine2(vals, cats, {min=75, max=90, h=230, suffix=' %'}={}){
  const W = 520, pl = 46, pr = 18, pt = 14, pb = 32, ih = h-pt-pb, iw = W-pl-pr, X = i => pl + iw*i/(vals.length-1), Y = v => pt + ih - (v-min)/(max-min)*ih; let g = '';
  for (let v=min; v<=max; v+=5) g += `<line x1="${pl}" x2="${W-pr}" y1="${Y(v)}" y2="${Y(v)}" stroke="var(--line)" stroke-dasharray="${v===min?0:3}"/><text x="${pl-10}" y="${Y(v)+4}" text-anchor="end" class="ub-c">${v}${suffix}</text>`;
  g += `<polyline class="ul-p" points="${vals.map((v,i)=>`${X(i)},${Y(v)}`).join(' ')}" fill="none" stroke="var(--i900)" stroke-width="2.5" stroke-linejoin="round"/>`;
  vals.forEach((v,i)=> g += `<circle cx="${X(i)}" cy="${Y(v)}" r="5" fill="var(--surface)" stroke="var(--i900)" stroke-width="2.5"><title>${cats[i]} : ${v}${suffix}</title></circle><text x="${X(i)}" y="${h-8}" text-anchor="middle" class="ub-c">${cats[i]}</text>`);
  return `<svg class="u-chart" viewBox="0 0 ${W} ${h}" width="100%" role="img">${g}</svg>`;
}
const uHBar = (label, val, max, color='var(--i900)', suffix='') => `<div class="mb-3"><div class="d-flex justify-content-between small fw-sb mb-1"><span>${label}</span><b>${val}${suffix}</b></div><div class="u-bar"><span style="width:${val/max*100}%;background:${color}"></span></div></div>`;

/* ----- Tableau de bord ----- */
view('a-dashboard','admin','Tableau de bord','fa-house-chimney', () => {
  const act = S.students.filter(s=>s.status==='Actif'), pre = S.preins.filter(c=>['recue','test_ok'].includes(c.stage)), oct = uOctTx().reduce((a,t)=>a+t.amount,0), late = uLate(), cert = S.students.filter(s=>s.status==='Certifié').length + Object.keys(S.certDone||{}).length;
  const pres = Math.round(act.reduce((a,s)=>a+s.presence,0)/Math.max(1,act.length)), byF = FORDER.map(f=>[f, S.students.filter(s=>s.f.includes(f)).length]), comb = S.students.filter(s=>s.f.length>1).length;
  const todo = [[pre.length,'warn','Préinscriptions à valider','a-preinscriptions'],[late.length,'bad','Paiements en retard','a-finances'],[toValidate().length,'info','Travaux à valider','a-travaux'],[S.tickets.filter(t=>t.st==='Ouvert').length,'cor','Tickets de support ouverts','a-support'],[S.sessions.filter(s=>s.trainer===null).length || 1,'cor','Sessions sans formateur','a-formations']].filter(x=>x[0]).slice(0,4);
  const dots = ['ok','info','warn','i9'];
  return `<div class="grid u-kpi5">
    ${uKpi('Étudiants actifs', act.length, '+12 ce mois-ci', '', '', 'ok')}
    ${uKpi('Préinscriptions à valider', pre.length, `${pre.filter(c=>uAgoN(c.d)>=2).length} depuis plus de 48 h`, '', '', 'warn')}
    ${uKpi('Encaissé en octobre', uM(oct), 'FCFA · objectif 9 M', '', '')}
    ${uKpi('Assiduité moyenne', `${pres} %`, 'Toutes formations', '', '')}
    ${uKpi('Certificats délivrés', cert, 'Depuis janvier', '', '')}</div>
  <div class="u-grid u-3-2 mt-4">${uCard('Nouvelles inscriptions par mois', uBars2(['Jan','Fév','Mar','Avr','Mai','Juin','Juil','Août','Sept','Oct'], [12,18,9,14,22,31,40,26,35,21], [9,13,8,11,16,24,33,19,29,17]), {tools:`<span class="legend"><span><i style="background:var(--i900)"></i>2026</span><span><i style="background:#C9C6E8"></i>2025</span></span>`})}
    ${uCard('Étudiants par formation', byF.map(([f,n],i)=>uHBar(esc(F[f].name), n, S.students.length, ['var(--i900)','var(--i500)','var(--i300)'][i])).join('') + uHBar('Profils combinés (plusieurs formations)', comb, S.students.length, '#C9C6E8'))}</div>
  <div class="u-grid u-1-1 mt-4">${uCard('À traiter', todo.map(([n,t,l,id])=>`<a class="lrow clickable text-decoration-none" href="#${id}" style="color:var(--fg)"><span class="nsq ${t}" style="width:36px;height:36px;flex-basis:36px;font-size:15px">${n}</span><span class="lr-m fw-sb">${l}</span><i class="fa-solid fa-chevron-right muted"></i></a>`).join(''))}
    <section class="dark-card align-self-start"><h3 class="h3" style="font-size:21px">Recouvrement</h3><div class="d-flex align-items-baseline gap-2 my-2 flex-wrap"><span class="num-key" style="font-size:44px;line-height:52px;color:#fff">87 %</span><span style="color:#C9C6E8">des échéances réglées à temps</span></div>${uBar(87)}<p class="mt-3">${late.length} étudiants ont une échéance en retard, pour un total de ${fcfa(late.reduce((a,x)=>a+x.amount,0))}.</p><a class="btn btn-primary mt-3" href="#a-finances">Voir les relances</a></section></div>
  ${uCard('Activité récente', `<ul class="act-list">${S.audit.slice(0,5).map((a,i)=>`<li><span class="ad ${dots[i%4]}"></span><div><div style="font-size:15px">${esc(a.a)} : ${esc(a.o)}</div><div class="small muted">${esc(a.d)} · ${esc(a.u)}</div></div></li>`).join('')}</ul>`, {cls:'mt-4', tools:canA('a-audit')?`<a class="link-u" href="#a-audit">Journal d'audit</a>`:''})}`;
});
Object.assign(VIEWS['a-dashboard'], {crumb:() => `Administration · ${TODAY.toLocaleDateString('fr-FR',{month:'long',year:'numeric'}).replace(/^./,c=>c.toUpperCase())}`, cta:`<button class="btn btn-primary t-cta" data-act="as-new"><i class="fa-solid fa-plus"></i>Nouvel étudiant</button>`});

/* ----- Étudiants : filtres, sélection groupée, tableau ----- */
const uAeList = () => { const F0 = S.ui.ae || {}, q = norm(F0.q||''); return S.students.filter(s=>(!q || norm(s.name+' '+s.id+' '+s.phone).includes(q)) && (!F0.f || s.f.includes(F0.f)) && (!F0.se || s.sessionId===F0.se) && (!F0.lv || s.group===F0.lv) && (!F0.pay || uPayTag(s)[0]===F0.pay)); };
function uAeRegion(){
  const L = uAeList(), sel = S.ui.asel = S.ui.asel || [], per = 10, pages = Math.max(1, Math.ceil(L.length/per)), pg = Math.min(S.ui.apg||1, pages), rows = L.slice((pg-1)*per, pg*per), allOn = rows.length && rows.every(s=>sel.includes(s.id));
  const pager = () => { const P = []; for (let i=1;i<=pages;i++) if (i<=3 || i===pages || Math.abs(i-pg)<=1) P.push(i); else if (P[P.length-1]!=='…') P.push('…'); return P.map(i=>i==='…'?'<span>…</span>':`<button class="${i===pg?'on':''}" data-act="u-apg" data-p="${i}">${i}</button>`).join(''); };
  return `${sel.length?`<div class="bulk-bar"><b>${sel.length} étudiant${sel.length>1?'s':''} sélectionné${sel.length>1?'s':''}</b><div class="ms-auto d-flex gap-2 flex-wrap"><button class="btn btn-white-line btn-sm" data-act="u-bulk" data-k="msg">Envoyer un message</button><button class="btn btn-white-line btn-sm" data-act="u-bulk" data-k="relance">Relancer le paiement</button><button class="btn btn-white-line btn-sm" data-act="u-bulk" data-k="groupe">Changer de niveau</button><button class="btn btn-white-line btn-sm btn-icon" data-act="u-bulk" data-k="clear" aria-label="Vider la sélection"><i class="fa-solid fa-xmark"></i></button></div></div>`:''}
  <section class="panel"><div class="tbl"><table class="table"><thead><tr><th style="width:52px"><input class="form-check-input" type="checkbox" ${allOn?'checked':''} data-chg="u-asel-all" aria-label="Tout sélectionner"></th><th>Étudiant</th><th>Formation · session</th><th>Niveau</th><th>Assiduité</th><th>Paiement</th><th>Dossier</th><th></th></tr></thead>
  <tbody>${rows.map(s=>{ const p = uPayTag(s), d = uDoss(s); return `<tr class="${sel.includes(s.id)?'sel':''}"><td><input class="form-check-input" type="checkbox" ${sel.includes(s.id)?'checked':''} data-chg="u-asel" data-id="${s.id}" aria-label="Sélectionner ${esc(s.name)}"></td><td><div class="d-flex align-items-center gap-3">${uIni(s.name,'sm')}<div><div class="tdn">${esc(s.name)}</div><div class="tds mono">${s.id}</div></div></div></td><td><div class="d-flex gap-1 flex-wrap">${s.f.map(fchip).join('')}</div><div class="tds">${esc(s.session.replace('Session ',''))}</div></td><td>${uLvlPill(s.group)}</td><td class="num fw-sb ${s.presence<80?'tx-bad':''}">${s.presence} %</td><td>${pill(p[0],p[1])}</td><td>${pill(d[0],d[1])}</td><td class="text-end"><button class="link-u" data-act="u-fiche" data-id="${s.id}">Ouvrir</button></td></tr>`; }).join('') || `<tr><td colspan="8">${uEmpty('Aucun étudiant ne correspond','Modifiez la recherche ou les filtres.')}</td></tr>`}</tbody></table></div>
  <div class="table-foot"><span>${L.length?`${(pg-1)*per+1}–${Math.min(pg*per,L.length)} sur ${L.length}`:'0 résultat'}</span><div class="pager">${pager()}</div></div></section>`;
}
view('a-etudiants','admin','Étudiants','fa-users', () => { const F0 = S.ui.ae = S.ui.ae || {};
  return `<div class="filters-row"><label class="search-field flex-grow-1 mb-0" style="min-width:240px"><i class="fa-solid fa-magnifying-glass"></i><input class="form-control" style="background:var(--surface)" placeholder="Nom, matricule, téléphone…" value="${esc(F0.q||'')}" data-inp="u-ae-q" aria-label="Rechercher un étudiant"></label>
    <select class="form-select" data-chg="u-ae" data-k="f" aria-label="Formation"><option value="">Toutes les formations</option>${FORDER.map(f=>`<option value="${f}" ${F0.f===f?'selected':''}>${esc(F[f].name)}</option>`).join('')}</select>
    <select class="form-select" data-chg="u-ae" data-k="se" aria-label="Session"><option value="">Toutes les sessions</option>${S.sessions.map(s=>`<option value="${s.id}" ${F0.se===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select>
    <select class="form-select" data-chg="u-ae" data-k="lv" aria-label="Niveau"><option value="">Tous les niveaux</option>${U_LEVELS.map(l=>`<option ${F0.lv===l?'selected':''}>${l}</option>`).join('')}</select>
    <select class="form-select" data-chg="u-ae" data-k="pay" aria-label="Paiement"><option value="">Paiement : tous</option>${['À jour','Échéance proche','En retard','Soldé'].map(x=>`<option ${F0.pay===x?'selected':''}>${x}</option>`).join('')}</select>
    <button class="btn btn-ghost" data-act="as-export"><i class="fa-solid fa-download"></i>Exporter</button></div>
  <div id="ae-region" class="mt-4">${uAeRegion()}</div>`; });
Object.assign(VIEWS['a-etudiants'], {crumb:() => `Administration <span class="sep">›</span> Étudiants · ${S.students.length} inscrits`, cta:`<button class="btn btn-primary t-cta" data-act="as-new"><i class="fa-solid fa-plus"></i>Ajouter un étudiant</button>`});
const uAePaint = () => { $('#ae-region').innerHTML = uAeRegion(); };
INP['u-ae-q'] = el => { S.ui.ae.q = el.value; S.ui.apg = 1; uAePaint(); };
INP['u-ae'] = el => { S.ui.ae[el.dataset.k] = el.value; S.ui.apg = 1; uAePaint(); };
INP['u-asel'] = el => { const a = S.ui.asel, i = a.indexOf(el.dataset.id); el.checked ? (i<0 && a.push(el.dataset.id)) : (i>=0 && a.splice(i,1)); uAePaint(); };
INP['u-asel-all'] = el => { const per = 10, L = uAeList(), pg = S.ui.apg||1, ids = L.slice((pg-1)*per, pg*per).map(s=>s.id); S.ui.asel = el.checked ? [...new Set([...S.ui.asel, ...ids])] : S.ui.asel.filter(x=>!ids.includes(x)); uAePaint(); };
ACT['u-apg'] = el => { S.ui.apg = +el.dataset.p; uAePaint(); };
ACT['u-bulk'] = el => { const k = el.dataset.k, ids = S.ui.asel, n = ids.length;
  if (k==='clear') { S.ui.asel = []; uAePaint(); return; }
  if (k==='msg') { S.ui.cmMode = 'sel'; S.ui.cmSel = [...ids]; go('a-communication'); return; }
  if (k==='relance') { S.relances = S.relances || {}; ids.forEach(id=>S.relances[id] = "SMS + e-mail · aujourd'hui"); audit('Relance de paiement', `${n} étudiant(s)`); toast(`Relance envoyée à ${n} étudiant${n>1?'s':''} (SMS, e-mail et notification).`); return; }
  if (k==='groupe') openModal({title:`Changer de niveau (${n})`, body:`<label class="form-label" for="cg-g">Nouveau niveau</label><select class="form-select" id="cg-g">${[...new Set(S.sessions.flatMap(s=>s.groups))].map(g=>`<option>${esc(g)}</option>`).join('')}</select>`, foot:`<button class="btn btn-ghost" data-bs-dismiss="modal">Annuler</button><button class="btn btn-primary" data-act="u-bulk-grp">Appliquer</button>`}); };
ACT['u-bulk-grp'] = () => { const g = $('#cg-g').value; S.students.filter(s=>S.ui.asel.includes(s.id)).forEach(s=>s.group = g); audit('Changement de niveau', `${S.ui.asel.length} étudiant(s) → ${g}`); closeModal(); toast(`${S.ui.asel.length} étudiant(s) affecté(s) au niveau ${esc(g)}.`); S.ui.asel = []; rerender(); };
ACT['u-fiche'] = el => uGo('a-fiche', {sid: el.dataset.id, ftb:'syn'});

/* ----- Fiche étudiant ----- */
view('a-fiche','admin','Fiche étudiant','fa-users', () => {
  const s = S.students.find(x=>x.id===S.ui.sid) || S.students[0], tab = S.ui.ftb || 'syn', p = uPayTag(s), d = uDoss(s), bal = uBal(s);
  S.notes = S.notes || {}; const N = S.notes[s.id] = S.notes[s.id] || [{t:'A demandé un échéancier décalé pour le solde. À étudier en commission.',w:'Service financier',d:'12 octobre'},{t:'Très bon niveau, proposé(e) pour le job dating du 21 novembre.',w:'Marc Yao',d:'8 octobre'}];
  let body = '';
  if (tab==='syn') { const sched = s.f.flatMap(f=>[[`Inscription · ${f}`, '06/10/2026', F[f].deposit],[`Solde · ${f}`, F[f].trancheDue, F[f].price-F[f].deposit]]); let cov = s.paid;
    body = `<div class="u-grid u-2-1"><div class="stack"><section class="panel card-pad"><h2 class="h3 mb-4" style="font-size:20px">Parcours</h2>${frise([{l:'Préinscription',s:'1er oct.'},{l:'Inscription',s:'6 oct.'},{l:'Formation',s:`${s.progress} %`},{l:'Évaluations',s:'—'},{l:'Certification',s:'Mars 2027'}], s.status==='Certifié'?5:2)}</section>
      <div class="grid g-kpi">${uKpi('Assiduité', `${s.presence} %`, s.presence>=80?'Au-dessus du seuil':'Sous le seuil de 80 %', '', '', s.presence>=80?'ok':'bad', 'compact')}${uKpi('Évaluations', `${Math.round(s.progress/100*5)} / 5`, `validées · ${Math.round(s.progress/100*16)} séances suivies`, '', '', '', 'compact')}${uKpi('Réglé', nfr(s.paid), `FCFA sur ${nfr(s.total)}`, '', '', '', 'compact')}${uKpi('Travaux en retard', hueOf(s.id)%5===0?2:0, hueOf(s.id)%5===0?'À relancer':'Aucun', '', '', hueOf(s.id)%5===0?'warn':'ok', 'compact')}</div>
      ${uCard('Échéancier', sched.map(([l,dt,a])=>{ const c = Math.min(cov,a); cov -= c; const st = c>=a ? ['Payé','ok'] : uAgoN(dt)>0 ? ['En retard','bad'] : c>0 ? ['Partiel','warn'] : ['À venir','warn']; return `<div class="d-flex align-items-center gap-3 py-3 border-bottom-soft"><span class="flex-grow-1">${l}</span><span class="muted d-none d-sm-inline" style="width:130px">${dt}</span><b class="num" style="width:130px;text-align:right">${fcfa(a)}</b><span style="width:96px;text-align:right">${pill(st[0],st[1])}</span></div>`; }).join(''))}</div>
      <div class="stack">${uCard('Coordonnées', `<div class="kv-col mb-3"><span>E-mail</span><b>${esc(s.email)}</b></div><div class="kv-col mb-3"><span>Téléphone</span><b>${esc(s.phone)}</b></div><div class="kv-col"><span>Pays · niveau</span><b>${esc(s.country)} · ${esc(s.group)}</b></div>`)}
      ${uCard('Notes internes', `${N.map(n=>`<div class="note-int"><div>${esc(n.t)}</div><div class="small muted mt-1">${esc(n.w)} · ${esc(n.d)}</div></div>`).join('')}<label class="form-label mt-3" for="ni-t">Ajouter une note</label><textarea class="form-control" id="ni-t" rows="2" placeholder="Visible uniquement par l'équipe EVC"></textarea><button class="btn btn-ghost btn-sm mt-2" data-act="u-note-add" data-id="${s.id}">Ajouter</button>`)}</div></div>`; }
  if (tab==='sco') body = `<div class="u-grid u-1-1">${s.f.map(f=>`<section class="panel card-pad c-${f}"><div class="d-flex align-items-center gap-2 mb-2">${fchip(f)}<h3 class="h3 mb-0">${esc(F[f].name)}</h3></div><div class="small muted mb-3">${esc(s.session)} · ${esc(s.group)} · formateur ${esc(F[f].trainer)}</div><div class="d-flex justify-content-between small fw-sb mb-1"><span>Progression</span><b>${s.progress} %</b></div>${uBar(s.progress)}<div class="d-flex justify-content-between small fw-sb mb-1 mt-3"><span>Assiduité</span><b>${s.presence} %</b></div>${uBar(s.presence, s.presence>=80?'ok':'bad')}<button class="btn btn-ghost btn-sm mt-3" data-act="as-view" data-id="${s.id}">Suivi détaillé</button></section>`).join('')}</div>`;
  if (tab==='fin') { const T = allTx().filter(t=>t.sid===s.id); body = `<section class="panel"><div class="tbl"><table class="table"><thead><tr><th>Date</th><th>Référence</th><th>Mode</th><th>Payé par</th><th class="text-end">Montant</th><th></th></tr></thead><tbody>${T.map(t=>`<tr><td>${t.d}</td><td class="mono">${t.ref}</td><td>${esc(t.mode)}</td><td>${esc(t.by||'Étudiant')}</td><td class="text-end num fw-sb">${fcfa(t.amount)}</td><td class="text-end"><button class="link-u" data-act="rec-open" data-r="${t.ref}">Reçu</button></td></tr>`).join('') || `<tr><td colspan="6">${uEmpty('Aucun paiement')}</td></tr>`}</tbody></table></div><div class="table-foot"><span>Reste à payer : <b class="text-body">${fcfa(bal)}</b></span><button class="btn btn-primary btn-sm" data-act="tx-new">Enregistrer un paiement</button></div></section>`; }
  if (tab==='doc') body = `<section class="panel">${["Pièce d'identité","Photo d'identité",'Dernier diplôme','Justificatif de domicile'].map((x,i)=>`<div class="row-item"><span class="ftype">${i===1?'JPG':'PDF'}</span><div class="ri-main"><div class="ri-t">${x}</div><div class="ri-s">Reçu le 1er octobre 2026</div></div>${d[0]==='Incomplet'&&i===3?pill('Manquant','bad'):pill('Validé','ok')}<button class="link-u ms-2" data-act="fake-dl" data-n="${x}">Voir</button></div>`).join('')}</section>`;
  if (tab==='hist') { const H = S.audit.filter(a=>(a.o||'').includes(s.name)||(a.o||'').includes(s.id)); body = uCard('Historique', `<ul class="act-list">${(H.length?H:[{a:'Inscription validée',o:s.id,d:'06/10/2026 10:12',u:'Awa Bamba'},{a:'Préinscription reçue',o:s.name,d:'01/10/2026 08:40',u:'Site web'}]).map(a=>`<li><span class="ad i9"></span><div><div>${esc(a.a)} : ${esc(a.o)}</div><div class="small muted">${esc(a.d)} · ${esc(a.u)}</div></div></li>`).join('')}</ul>`); }
  return `<section class="panel card-pad d-flex align-items-center gap-4 flex-wrap"><span class="ini" style="width:72px;height:72px;font-size:24px;background:var(--c300);font-family:var(--f-display)">${esc(initials(s.name))}</span><div class="flex-grow-1" style="min-width:220px"><h2 class="h2 mb-0" style="font-size:24px">${esc(s.name)}</h2><div class="muted">${s.id} · ${s.f.map(f=>esc(uFShort(f))).join(' + ')} · ${esc(s.session)}</div><div class="d-flex gap-2 mt-2 flex-wrap">${stPill(s.status)}${p[0]!=='À jour'&&p[0]!=='Soldé'?pill(p[0],p[1]):''}${pill(`Dossier ${d[0].toLowerCase()}`, d[1])}</div></div><div class="d-flex gap-2 flex-wrap"><button class="btn btn-ghost" data-act="msg-new">Envoyer un message</button><button class="btn btn-ghost" data-act="fake-dl" data-n="Attestation ${s.id}">Générer une attestation</button><button class="btn btn-indigo" data-act="as-edit" data-id="${s.id}">Modifier</button></div></section>
  <div class="mt-4">${uTabs([['syn','Synthèse'],['sco','Scolarité'],['fin','Finances'],['doc','Documents'],['hist','Historique']], tab, 'u-ftb')}</div>${body}`;
});
