/* ----- Préinscriptions ----- */
const U_PRT = {todo:['À traiter',c=>['recue','test_ok'].includes(c.stage)], wait:['Attente candidat',c=>['profil_ok','test_ko'].includes(c.stage)], ok:['Validées',c=>['paye','actif'].includes(c.stage)], ko:['Refusées',c=>c.stage==='rejete']};
view('a-preinscriptions','admin','Préinscriptions','fa-tray', () => {
  const k = S.ui.prt || 'todo', L = S.preins.filter(U_PRT[k][1]), c = L.find(x=>x.id===S.ui.pre) || L[0];
  const docsN = x => x.docs ? 4 : 3, fees = x => x.pay ? pill('Réglés','ok') : pill('En attente','warn');
  let det = '';
  if (c) { const pieces = [["Pièce d'identité", c.docs],["Photo d'identité",true],['Dernier diplôme',true],['Justificatif de domicile', c.docs]];
    const acts = {recue:`<button class="btn btn-primary w-100" data-act="cand-review" data-id="${c.id}">Étudier et valider le profil</button><div class="d-flex gap-2 mt-2"><button class="btn btn-ghost flex-grow-1" data-act="cand-askdoc" data-id="${c.id}">Demander un complément</button><button class="btn btn-danger-line" data-act="cand-reject" data-id="${c.id}">Refuser</button></div>`,
      profil_ok:`<button class="btn btn-ghost w-100" data-act="cand-remind" data-id="${c.id}">Relancer le test d'éligibilité</button>`, test_ok:`<button class="btn btn-primary w-100" data-act="cand-cash" data-id="${c.id}">Encaisser le 1er versement</button><button class="btn btn-ghost w-100 mt-2" data-act="cand-review" data-id="${c.id}">Revoir le dossier</button>`,
      test_ko:`<button class="btn btn-ghost w-100" data-act="cand-retry" data-id="${c.id}">Accorder une nouvelle tentative</button><button class="btn btn-danger-line w-100 mt-2" data-act="cand-reject" data-id="${c.id}">Refuser</button>`,
      paye:`<button class="btn btn-ghost w-100" data-act="cand-link" data-id="${c.id}">Renvoyer le lien d'activation</button>`, actif:`<button class="btn btn-ghost w-100" data-act="u-fiche" data-id="${c.mat||''}">Ouvrir la fiche étudiant</button>`, rejete:''}[c.stage];
    det = `<section class="panel card-pad pre-det"><div class="d-flex align-items-center gap-3 mb-3">${uIni(c.name)}<div><h2 class="h3 mb-0" style="font-size:20px">${esc(c.name)}</h2><div class="small muted">${c.f.map(uFShort).join(' + ')} · ${esc(c.session.replace('Session ','session '))}</div></div></div>
      <div class="kv"><span>Téléphone</span><b>${esc(c.phone)}</b></div><div class="kv"><span>Né(e) le</span><b>${esc(c.birth)}</b></div><div class="kv"><span>Format souhaité</span><b>${esc(c.mode)}</b></div><div class="kv"><span>Étape</span>${stagePill(c.stage)}</div>
      <h3 class="h3 mt-3 mb-2" style="font-size:16px">Pièces justificatives</h3>${pieces.map(([t,ok])=>`<div class="lrow" style="padding:10px 14px"><span class="crit-ic ${ok?'ok':'warn'}" style="width:26px;height:26px;font-size:12px">${ok?'<i class="fa-solid fa-check"></i>':'!'}</span><span class="lr-m fw-sb small">${t}</span>${ok?`<button class="link-u small" data-act="fake-dl" data-n="${t}">Voir</button>`:`<button class="link-u small" data-act="cand-askdoc" data-id="${c.id}">Relancer</button>`}</div>`).join('')}
      <div class="alert-strip as-info slim mt-3 small">La validation envoie le test d'éligibilité ; le premier versement crée ensuite le compte, attribue le matricule et envoie les identifiants par e-mail et SMS.</div>
      <div class="mt-3">${acts}</div></section>`; }
  return `<div class="chips mb-4">${Object.entries(U_PRT).map(([x,[l,fn]])=>`<button class="chip-filter ${x===k?'on':''}" data-act="u-prt" data-k="${x}">${l} (${S.preins.filter(fn).length})</button>`).join('')}</div>
  <div class="u-grid u-2-1 pre-grid"><section class="panel align-self-start"><div class="tbl"><table class="table"><thead><tr><th>Candidat</th><th>Formation</th><th>Pièces</th><th>Frais</th><th>Reçue</th></tr></thead><tbody>${L.map(x=>`<tr class="clickable ${c&&x.id===c.id?'sel':''}" data-act="u-pre" data-id="${x.id}"><td><div class="tdn">${esc(x.name)}</div><div class="tds">${esc(x.email)}</div></td><td>${x.f.map(fchip).join(' ')}</td><td class="fw-sb ${docsN(x)===4?'tx-ok':'tx-warn'}">${docsN(x)}/4</td><td>${fees(x)}</td><td class="${uAgoN(x.d)>=2&&k==='todo'?'tx-bad fw-sb':''}">${uAgo(x.d)}</td></tr>`).join('') || `<tr><td colspan="5">${uEmpty('Aucune candidature','Rien à traiter dans cette catégorie.')}</td></tr>`}</tbody></table></div></section>${det}</div>`;
});
VIEWS['a-preinscriptions'].crumb = () => `Administration <span class="sep">›</span> Préinscriptions · ${S.preins.filter(U_PRT.todo[1]).length} à traiter`;
