view('a-finances','admin','Finances et relances','fa-credit-card', () => {
  const oct = uOctTx().reduce((a,t)=>a+t.amount,0), late = uLate(), lateSum = late.reduce((a,x)=>a+x.amount,0), sel = S.ui.fsel2 = S.ui.fsel2 || late.map(x=>x.s.id), auto = S.autoRel !== false;
  const allOn = late.length && late.every(x=>sel.includes(x.s.id)), last = allTx().filter(t=>!t.cancelled).sort((a,b)=>uAgoN(a.d)-uAgoN(b.d)).slice(0,4);
  return `<div class="grid g-kpi">${uKpi('Encaissé ce mois-ci', uM(oct), `FCFA · ${Math.round(oct/9e6*100)} % de l'objectif`, '', '')}${uKpi("Attendu d'ici fin octobre", '1,6 M', 'FCFA · 11 échéances', '', '')}${uKpi('Montant en retard', `<span class="tx-bad">${uM(lateSum)}</span>`, `FCFA · ${late.length} étudiants`, '', '')}${uKpi('Taux de recouvrement', '<span class="tx-ok">87 %</span>', 'Échéances réglées à temps', '', '')}</div>
  <div class="u-grid u-2-1 mt-4"><section class="panel align-self-start"><div class="panel-h panel-sep"><h2>Échéances en retard (${late.length})</h2><div class="tools"><button class="btn btn-primary btn-sm" data-act="u-rel-sel">Relancer la sélection${sel.length?` (${sel.length})`:''}</button></div></div><div class="tbl"><table class="table"><thead><tr><th style="width:52px"><input class="form-check-input" type="checkbox" ${allOn?'checked':''} data-chg="u-fs-all" aria-label="Tout sélectionner"></th><th>Étudiant</th><th>Montant dû</th><th>Retard</th><th>Dernière relance</th><th></th></tr></thead><tbody>${late.map(x=>`<tr><td><input class="form-check-input" type="checkbox" ${sel.includes(x.s.id)?'checked':''} data-chg="u-fs" data-id="${x.s.id}" aria-label="Sélectionner ${esc(x.s.name)}"></td><td><div class="tdn">${esc(x.s.name)}</div><div class="tds">${x.s.f.map(uFShort).join(' + ')}</div></td><td class="num fw-sb" style="font-family:var(--f-display)">${fcfa(x.amount)}</td><td>${pill(`${x.days} jours`, x.days>=15?'bad':'warn')}</td><td class="small muted">${esc(x.last)}</td><td class="text-end"><button class="link-u" data-act="u-fiche" data-id="${x.s.id}">Voir</button></td></tr>`).join('') || `<tr><td colspan="6">${uEmpty('Aucune échéance en retard','Bravo, tous les étudiants sont à jour.')}</td></tr>`}</tbody></table></div></section>
  <div class="stack"><section class="panel card-pad"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h3 mb-0" style="font-size:19px">Relances automatiques</h2><div class="form-check form-switch m-0"><input class="form-check-input" type="checkbox" role="switch" ${auto?'checked':''} data-chg="u-autorel" aria-label="Relances automatiques"></div></div>${[['J − 7','info','Rappel avant échéance','SMS et e-mail'],['J + 1','warn','Première relance','SMS, e-mail et notification'],['J + 7','warn','Deuxième relance','E-mail · copie au service financier'],['J + 15','bad','Suspension des évaluations','Accès rétabli dès le paiement']].map(([j,t,a,b])=>`<div class="d-flex gap-3 align-items-start py-2 ${auto?'':'opacity-50'}"><span class="pill p-${t} nodot" style="min-width:58px;justify-content:center">${j}</span><div><div class="fw-sb small">${a}</div><div class="small muted">${b}</div></div></div>`).join('')}<a class="link-u small mt-2 d-inline-block" href="#a-communication">Modifier les règles et les messages</a></section>
    ${uCard('Derniers encaissements', last.map(t=>`<div class="d-flex justify-content-between gap-2 py-2 border-bottom-soft"><div><div class="fw-sb small">${esc(t.s)}</div><div class="small muted">${esc(t.mode)} · ${uAgo(t.d).toLowerCase()}</div></div><b class="tx-ok num nowrap">+ ${nfr(t.amount)}</b></div>`).join(''))}</div></div>
  ${uCard('Journal des encaissements', `<div id="r-tx">${txRegion()}</div>`, {cls:'mt-4', p0:true, tools:`<button class="btn btn-ghost btn-sm" data-act="r-export" data-t="finances">Exporter</button>`})}`;
});
Object.assign(VIEWS['a-finances'], {crumb:() => `Administration <span class="sep">›</span> Finances · ${TODAY.toLocaleDateString('fr-FR',{month:'long',year:'numeric'})}`, cta:`<button class="btn btn-primary t-cta" data-act="tx-new"><i class="fa-solid fa-plus"></i>Enregistrer un paiement</button>`});
INP['u-fs'] = el => { const a = S.ui.fsel2, i = a.indexOf(el.dataset.id); el.checked ? (i<0 && a.push(el.dataset.id)) : (i>=0 && a.splice(i,1)); rerender(); };
