ACT['u-rel-sel'] = () => { const ids = S.ui.fsel2; if (!ids.length) { toast('Sélectionnez au moins un étudiant.','warn'); return; } S.relances = S.relances || {}; ids.forEach(id=>S.relances[id] = "SMS + e-mail · aujourd'hui"); audit('Relance de paiement', `${ids.length} étudiant(s)`); rerender(); toast(`Relance envoyée à ${ids.length} étudiant${ids.length>1?'s':''} (SMS, e-mail et notification).`); };

/* ----- Certifications : contrôle d'éligibilité ----- */
view('a-certifications','admin','Certifications','fa-award', () => {
  S.certDone = S.certDone || {}; const se = S.ui.cses || 'S-2026-06', L = S.students.filter(s=>s.sessionId===se && s.status!=='Archivé');
  const row = s => { const h = hueOf(s.id), b = uBal(s), seances = Math.min(16, Math.round(s.progress/100*16)+(h%3)), pr = typeof uSProj==='function' ? uSProj(s) : [], left = pr.filter(x=>x.status!=='valide').length, dos = uDoss(s)[0]==='Complet';
    const c = [[s.presence>=80, `${s.presence} %`, s.presence<80], [seances>=14, `${seances}/16`, false], [b===0, b===0?'Soldé':uM(b).replace(' M',' M'), false], [left===0, left===0?`${pr.length}/${pr.length}`:`${left} non réalisé${left>1?'s':''}`, left>2], [dos, dos?'Complet':'1 pièce', false]];
    const ok = c.every(x=>x[0]), ko = c.some(x=>x[2]), done = s.f.every(f=>S.certDone[s.id+f]);
    return {s, c, ok, ko, done}; };
  const R = L.map(row), el = R.filter(r=>r.ok).length, reg = R.filter(r=>!r.ok && !r.ko).length, ne = R.filter(r=>r.ko).length, toSign = R.filter(r=>r.ok && !r.done).length;
  const cell = ([ok, txt, bad]) => `<span class="pill ${ok?'p-ok':bad?'p-bad':txt==='Prévu'?'p-warn':'p-bad'} nodot">${ok?'✓ ':txt==='Prévu'?'':'✗ '}${esc(txt)}</span>`;
  return `<div class="d-flex gap-3 flex-wrap align-items-end"><div style="min-width:300px"><label class="form-label" for="cs-se">Session</label><select class="form-select" id="cs-se" data-chg="u-cses">${S.sessions.map(s=>`<option value="${s.id}" ${s.id===se?'selected':''}>${esc(s.name)} (fin le ${s.end})</option>`).join('')}</select></div>
    <div class="u-grid flex-grow-1" style="grid-template-columns:repeat(3,minmax(140px,1fr))">${uKpi('Éligibles', el, '', '', '', '', 'compact tone-ok')}${uKpi('À régulariser', reg, '', '', '', '', 'compact tone-warn')}${uKpi('Non éligibles', ne, '', '', '', '', 'compact tone-bad')}</div></div>
  <div class="u-grid u-2-1 mt-4"><section class="panel align-self-start"><div class="tbl"><table class="table cert-tb"><thead><tr><th>Étudiant</th><th class="text-center">Assiduité ≥ 80 %</th><th class="text-center">Séances validées</th><th class="text-center">Frais soldés</th><th class="text-center">Projets réalisés</th><th class="text-center">Dossier</th><th>Décision</th></tr></thead><tbody>${R.map(r=>`<tr><td class="tdn">${esc(r.s.name)}</td>${r.c.map(x=>`<td class="text-center">${cell(x)}</td>`).join('')}<td>${r.ok ? (r.done ? `<button class="link-u" data-act="cert-view" data-id="${r.s.id}" data-f="${r.s.f[0]}">Voir le certificat</button>` : `<button class="btn btn-primary btn-sm" data-act="cert-gen" data-id="${r.s.id}" data-f="${r.s.f[0]}">Générer le certificat</button>`) : r.ko ? '<span class="fw-sb tx-bad small">Non éligible</span>' : '<span class="fw-sb tx-warn small">À régulariser</span>'}</td></tr>`).join('') || `<tr><td colspan="7">${uEmpty('Aucun étudiant dans cette session')}</td></tr>`}</tbody></table></div></section>
  <div class="stack"><div class="dark-card"><h3 class="h3" style="font-size:20px">${toSign} certificat${toSign>1?'s':''} à signer</h3><p class="mt-2 small">${esc(S.sessions.find(s=>s.id===se).name)}. Signature électronique de la direction requise avant l'envoi aux étudiants.</p><button class="btn btn-primary w-100 mt-3" data-act="u-cert-sign" ${toSign?'':'disabled'}>Signer et envoyer</button></div>
    ${uCard("Règles d'éligibilité", [['Assiduité minimale','80 %'],['Séances validées','14 / 16'],['Frais de formation','Soldés'],['Projets','Aucun projet non réalisé'],['Dossier administratif','Complet']].map(([a,b])=>`<div class="kv border-bottom-soft py-2"><span>${a}</span><b>${b}</b></div>`).join('') + `<a class="link-u small mt-3 d-inline-block" href="#a-parametres">Modifier les règles</a>`)}</div></div>`;
});
VIEWS['a-certifications'].crumbTail = "Contrôle d'éligibilité";
INP['u-cses'] = el => { S.ui.cses = el.value; rerender(); };
ACT['u-cert-sign'] = () => { const se = S.ui.cses || 'S-2026-06'; let n = 0; S.students.filter(s=>s.sessionId===se).forEach(s=>{ const h = hueOf(s.id), b = uBal(s), seances = Math.min(16, Math.round(s.progress/100*16)+(h%3)), proj = h%5===0 ? null : 11 + h%8; if (s.presence>=80 && seances>=14 && b===0 && proj!=null && proj>=10 && uDoss(s)[0]==='Complet') s.f.forEach(f=>{ if (!S.certDone[s.id+f]) { S.certDone[s.id+f] = true; n++; } }); }); audit('Certificats signés', `${n} certificat(s)`); rerender(); toast(`${n} certificat${n>1?'s':''} signé${n>1?'s':''} et envoyé${n>1?'s':''} aux étudiants.`); };

/* ----- Rapports et statistiques ----- */
view('a-rapports','admin','Rapports','fa-file-invoice', () => {
  const per = S.ui.rper || 'trim', ff = S.ui.rff || '';
  S.reps = S.reps || [['PDF','Rapport trimestriel · juillet à septembre 2026','Généré le 3 octobre par Awa Bamba'],['XLS','Impayés au 30 septembre 2026','Généré le 1er octobre par le service financier'],['PDF','Assiduité · septembre 2026','Généré le 30 septembre · envoi automatique']];
  const att = FORDER.map(f=>[F[f].name, F[f].presence>=80?F[f].presence:F[f].presence]).concat([['Profils combinés', 84]]);
  const types = [['fa-users','Effectifs','Inscrits, abandons, répartition par formation et par session'],['fa-clipboard-check','Assiduité','Présences, retards et absences par niveau'],['fa-chart-column','Résultats','Compétences validées, taux de réussite, séances à rattraper'],['fa-credit-card','Finances','Encaissements, impayés, recouvrement'],['fa-award','Certifications','Éligibles, délivrés, en attente'],['fa-briefcase','Insertion','Stages, emplois et missions obtenus']];
  return `<div class="d-flex gap-2 flex-wrap align-items-center">${uSeg([['mois','Mois'],['trim','Trimestre'],['annee','Année']], per, 'u-rper')}<select class="form-select" style="width:auto;min-width:220px" data-chg="u-rff" aria-label="Formation"><option value="">Toutes les formations</option>${FORDER.map(f=>`<option value="${f}" ${ff===f?'selected':''}>${esc(F[f].name)}</option>`).join('')}</select><div class="ms-auto d-flex gap-2"><button class="btn btn-ghost" data-act="u-rep-xls">Exporter en Excel</button><button class="btn btn-primary" data-act="u-rep" data-t="Rapport ${per==='mois'?'mensuel':per==='trim'?'trimestriel':'annuel'}">Générer le rapport PDF</button></div></div>
  <div class="u-grid u-1-1 mt-4">${uCard('Taux de réussite aux évaluations', `<div class="small muted mb-2">Part des évaluations validées, par mois</div>${uLine2(per==='annee'?[74,77,79,81,83,86]:[78,80,81,83,84,86], per==='annee'?['2021','2022','2023','2024','2025','2026']:['Mai','Juin','Juil.','Août','Sept.','Oct.'], {min:70,max:90})}`)}
    ${uCard('Assiduité par formation', `<div class="att-bars">${att.map(([l,v])=>`<div class="ab-row"><span class="small">${esc(l)}</span><div class="ab-track"><span style="width:${v}%;background:${v<80?'var(--bad)':'var(--i900)'}"></span><i class="ab-th" style="left:80%"></i></div><b class="small num">${v} %</b></div>`).join('')}</div><div class="small muted mt-2"><span style="display:inline-block;width:14px;height:2px;background:var(--c500);vertical-align:middle;margin-right:6px"></span>Seuil requis pour la certification : 80 %</div>`)}</div>
  <h2 class="h2 mt-4 mb-3">Rapports types</h2><div class="u-grid rep-grid">${types.map(([ic,t,d])=>`<div class="rep-card"><i class="fa-solid ${ic} tx-c" style="font-size:20px"></i><b>${t}</b><span class="small muted">${d}</span><button class="link-u small mt-auto" data-act="u-rep" data-t="${t}">Générer</button></div>`).join('')}</div>
  ${uCard('Derniers rapports générés', S.reps.map(([ty,t,d])=>`<div class="d-flex align-items-center gap-3 py-2 border-bottom-soft"><span class="ftype" style="${ty==='XLS'?'color:var(--ok);background:var(--ok-soft);border:0':'background:var(--c100);border:0'}">${ty}</span><div class="lr-m"><div class="fw-sb small">${esc(t)}</div><div class="small muted">${esc(d)}</div></div><button class="link-u small" data-act="fake-dl" data-n="${esc(t)}">Télécharger</button></div>`).join(''), {cls:'mt-4'})}`;
});
VIEWS['a-rapports'].title = 'Rapports et statistiques';
INP['u-rff'] = el => { S.ui.rff = el.value; rerender(); };
ACT['u-rep'] = el => { const per = {mois:'octobre 2026', trim:'juillet à septembre 2026', annee:'année 2026'}[S.ui.rper||'trim']; S.reps.unshift(['PDF', `${el.dataset.t} · ${per}${S.ui.rff?' · '+S.ui.rff:''}`, "Généré à l'instant par Didier Koné"]); audit('Rapport généré', el.dataset.t); rerender(); toast(`Rapport « ${esc(el.dataset.t)} » généré. Il est disponible ci-dessous.`); };
ACT['u-rep-xls'] = () => showCSV('Rapport — effectifs et résultats', [['Formation','Inscrits','Assiduité','Taux de réussite'], ...FORDER.map(f=>[F[f].name, S.students.filter(s=>s.f.includes(f)).length, F[f].presence+' %', '84 %'])]);

/* ----- Utilisateurs et rôles ----- */
const U_PMX_MOD = ['Étudiants et dossiers','Préinscriptions','Formations et sessions','Séances et présences','Travaux et évaluations','Paiements et relances','Certifications','Rapports','Paramètres'];
const U_PMX_ROLES = ['Super Administrateur','Responsable pédagogique','Responsable financier','Formateur principal'];
view('a-roles','admin','Utilisateurs et rôles','fa-sliders', () => {
  const tab = S.ui.rtab || 'users';
  S.users = S.users || [['Didier Koné','d.kone@evc.ci','Super Administrateur',"Aujourd'hui, 08 h 12",'Actif'],['Awa Bamba','a.bamba@evc.ci','Responsable administratif',"Aujourd'hui, 09 h 40",'Actif'],['Jean Kouakou','j.kouakou@evc.ci','Responsable pédagogique','Hier, 17 h 05','Actif'],['Mariam Soro','m.soro@evc.ci','Responsable financier','Hier, 16 h 20','Actif'],['Marc Yao','m.yao@evc.ci','Formateur principal',"Aujourd'hui, 10 h 01",'Actif'],['Inès Gbagbo','i.gbagbo@evc.ci','Formateur adjoint','Il y a 2 jours','Actif'],['Paul Konan','p.konan@evc.ci','Formateur adjoint','Jamais','Invitation envoyée']];
  S.pmx = S.pmx || [['E','E','V','V'],['E','E','V','-'],['E','E','-','V'],['E','E','-','E'],['E','E','-','E'],['E','V','E','-'],['E','E','V','-'],['E','E','V','-'],['E','-','-','-']];
  const tabs = uTabs([['users','Utilisateurs et rôles'],['matrix','Matrice détaillée'],['etab','Établissement'],['pay','Moyens de paiement']], tab, 'u-rtab');
  if (tab==='matrix') return tabs + UVA_OLD['a-roles']();
  if (tab==='etab') return tabs + UVA_OLD['a-parametres']();
  if (tab==='pay') { S.pms = S.pms || {'Orange Money':1,'MTN Mobile Money':1,'Wave':1,'Moov Money':1,'Carte bancaire':1,'Espèces (guichet Cocody)':1,'Virement bancaire':0}; return tabs + `<section class="panel">${Object.keys(S.pms).map(m=>`<div class="row-item"><span class="nsq" style="width:40px;height:40px;flex-basis:40px;background:var(--i100);color:var(--i900)"><i class="fa-solid ${/Carte/.test(m)?'fa-credit-card':/Espèces/.test(m)?'fa-money-bill-wave':/Virement/.test(m)?'fa-building-columns':'fa-mobile-screen'}"></i></span><div class="ri-main"><div class="ri-t">${m}</div><div class="ri-s">${S.pms[m]?'Proposé aux étudiants':'Désactivé'}</div></div><div class="form-check form-switch m-0"><input class="form-check-input" type="checkbox" role="switch" ${S.pms[m]?'checked':''} data-chg="u-pms" data-k="${esc(m)}" aria-label="${m}"></div></div>`).join('')}</section>`; }
  const pv = v => v==='E' ? '<span class="pill p-ok nodot">Modifier</span>' : v==='V' ? '<span class="pill p-info nodot">Voir</span>' : '<span class="muted">—</span>';
  return tabs + `<section class="panel"><div class="tbl"><table class="table"><thead><tr><th>Utilisateur</th><th>Rôle</th><th>Dernière connexion</th><th>Statut</th><th></th></tr></thead><tbody>${S.users.map((u,i)=>`<tr><td><div class="d-flex align-items-center gap-3">${uIni(u[0],'sm')}<div><div class="tdn">${esc(u[0])}</div><div class="tds">${esc(u[1])}</div></div></div></td><td>${pill(u[2], uRoleTone(u[2]))}</td><td>${esc(u[3])}</td><td>${pill(u[4], u[4]==='Actif'?'ok':u[4]==='Suspendu'?'bad':'warn')}</td><td class="text-end"><button class="link-u" data-act="u-user-ed" data-i="${i}">Modifier</button></td></tr>`).join('')}</tbody></table></div></section>
  <section class="panel mt-4"><div class="panel-h panel-sep"><h2>Permissions par rôle</h2><div class="tools small"><span class="tx-ok fw-sb">Modifier</span><span class="muted">: lecture et écriture</span><span class="tx-info fw-sb ms-2">Voir</span><span class="muted">: lecture seule</span><span class="muted ms-2">— : aucun accès</span></div></div><div class="tbl"><table class="table pmx"><thead><tr><th>Module</th>${U_PMX_ROLES.map(r=>`<th class="text-center" style="text-transform:none;letter-spacing:0;font-size:14px;color:var(--fg)">${r}</th>`).join('')}</tr></thead><tbody>${U_PMX_MOD.map((m,i)=>`<tr><td class="tdn">${m}</td>${U_PMX_ROLES.map((r,j)=>`<td class="text-center"><button class="pmx-b" data-act="u-pmx" data-i="${i}" data-j="${j}" title="Cliquer pour changer" ${j===0?'disabled':''}>${pv(S.pmx[i][j])}</button></td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;
});
Object.assign(VIEWS['a-roles'], {crumbTail:'Paramètres', cta:`<button class="btn btn-primary t-cta" data-act="u-invite"><i class="fa-solid fa-plus"></i>Inviter un utilisateur</button>`});
ACT['u-pmx'] = el => { const i = +el.dataset.i, j = +el.dataset.j, c = {E:'V', V:'-', '-':'E'}; S.pmx[i][j] = c[S.pmx[i][j]]; audit('Permission modifiée', `${U_PMX_MOD[i]} — ${U_PMX_ROLES[j]}`); rerender(); };
INP['u-pms'] = el => { S.pms[el.dataset.k] = el.checked ? 1 : 0; rerender(); toast(`${esc(el.dataset.k)} ${el.checked?'activé':'désactivé'}.`, el.checked?'ok':'info'); };
ACT['u-invite'] = () => openModal({title:'Inviter un utilisateur', body:`<form id="uinv" data-submit="u-invite-ok" class="d-flex flex-column gap-3" novalidate><div><label class="form-label" for="ui-n">Nom complet</label><input class="form-control" id="ui-n" required><div class="invalid-feedback">Indiquez le nom.</div></div><div><label class="form-label" for="ui-e">Adresse e-mail</label><input class="form-control" type="email" id="ui-e" required placeholder="prenom.nom@evc.ci"><div class="invalid-feedback">E-mail invalide.</div></div><div><label class="form-label" for="ui-r">Rôle</label><select class="form-select" id="ui-r">${ADMIN_ROLES.map(r=>`<option>${esc(r)}</option>`).join('')}</select></div></form>`, foot:`<button class="btn btn-ghost" data-bs-dismiss="modal">Annuler</button><button class="btn btn-primary" type="submit" form="uinv">Envoyer l'invitation</button>`});
ACT['u-invite-ok'] = () => { S.users.push([$('#ui-n').value.trim(), $('#ui-e').value.trim(), $('#ui-r').value, 'Jamais', 'Invitation envoyée']); audit('Invitation envoyée', $('#ui-e').value); closeModal(); rerender(); toast('Invitation envoyée par e-mail.'); };
ACT['u-user-ed'] = el => { const u = S.users[+el.dataset.i]; openModal({title:`Modifier · ${esc(u[0])}`, body:`<div class="d-flex flex-column gap-3"><div><label class="form-label" for="ue-r">Rôle</label><select class="form-select" id="ue-r">${ADMIN_ROLES.map(r=>`<option ${r===u[2]?'selected':''}>${esc(r)}</option>`).join('')}</select></div><div><label class="form-label" for="ue-s">Statut</label><select class="form-select" id="ue-s">${['Actif','Suspendu','Invitation envoyée'].map(s=>`<option ${s===u[4]?'selected':''}>${s}</option>`).join('')}</select></div></div>`, foot:`<button class="btn btn-ghost" data-bs-dismiss="modal">Annuler</button><button class="btn btn-primary" data-act="u-user-ok" data-i="${el.dataset.i}">Enregistrer</button>`}); };
ACT['u-user-ok'] = el => { const u = S.users[+el.dataset.i]; u[2] = $('#ue-r').value; u[4] = $('#ue-s').value; audit('Utilisateur modifié', `${u[0]} — ${u[2]} — ${u[4]}`); closeModal(); rerender(); toast('Utilisateur mis à jour.'); };
